import puppeteer from 'puppeteer';
import fs from 'fs';
import path from 'path';

const BASE_URL = 'http://localhost:5173';
const SCREENSHOT_DIR = 'c:/Users/asifk/Documents/antigravity/HMS/docs/screenshots';

if (!fs.existsSync(SCREENSHOT_DIR)) {
    fs.mkdirSync(SCREENSHOT_DIR, { recursive: true });
}

const routes = [
    { name: '01_Dashboard', path: '/' },
    { name: '02_Patients', path: '/patients' },
    { name: '03_Appointments', path: '/appointments' },
    { name: '04_EMR', path: '/emr' },
    { name: '05_Billing', path: '/billing' },
    { name: '06_Pharmacy', path: '/pharmacy' },
    { name: '07_Lab', path: '/lab' },
    { name: '08_Beds', path: '/beds' },
    { name: '09_Staff', path: '/staff' },
    { name: '10_Reports', path: '/reports' },
    { name: '11_Inventory', path: '/inventory' },
    { name: '12_BloodBank', path: '/bloodbank' }
];

async function capture() {
    const browser = await puppeteer.launch({ headless: true });
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });

    console.log('Navigating to signup...');
    await page.goto(`${BASE_URL}/signup`, { waitUntil: 'networkidle0' });

    // Fill signup form
    console.log('Signing up...');
    try {
        await page.type('input[placeholder="Jane Admin"]', 'Doc Admin');
        await page.type('input[placeholder="name@hospital.com"]', 'admin' + Date.now() + '@hms.com');
        await page.type('input[placeholder="Enter your username"]', 'admin_' + Date.now());
        await page.type('input[placeholder="********"]', 'password123');
        // Type confirm password
        const confirmInputs = await page.$$('input[placeholder="Confirm password"]');
        if (confirmInputs.length > 0) {
            await confirmInputs[0].type('password123');
        }
        await page.select('select', 'Admin');
        await page.click('button[type="submit"]');

        await page.waitForNavigation({ waitUntil: 'networkidle0' });
        console.log('Logged in successfully!');
    } catch (e) {
        console.log('Signup failed or already logged in, attempting login...');
    }

    // Capture each page
    for (const route of routes) {
        console.log(`Capturing ${route.name}...`);
        await page.goto(`${BASE_URL}${route.path}`, { waitUntil: 'networkidle0' });
        // Wait for some time for animations/charts to load
        await new Promise(r => setTimeout(r, 2000));
        await page.screenshot({ 
            path: path.join(SCREENSHOT_DIR, `${route.name}.png`),
            fullPage: false 
        });
    }

    await browser.close();
    console.log('All screenshots captured!');
}

capture().catch(console.error);

import puppeteer from 'puppeteer';
import fs from 'fs';
import path from 'path';

const DOC_PATH = 'C:/Users/asifk/.gemini/antigravity/brain/8b0c8b40-f92d-4c95-9380-5e84874b0c69/application_overview.md';
const OUTPUT_PATH = 'C:/Users/asifk/Documents/antigravity/HMS/HMS_Documentation.pdf';

async function generatePDF() {
    console.log('Reading documentation...');
    let markdown = fs.readFileSync(DOC_PATH, 'utf8');

    // Simple Markdown to HTML converter for the specific document structure
    let htmlContent = markdown
        .replace(/^# (.+)$/gm, '<h1>$1</h1>')
        .replace(/^## (.+)$/gm, '<h2>$1</h2>')
        .replace(/^### (.+)$/gm, '<h3>$1</h3>')
        .replace(/^\*\*([^*]+)\*\*/gm, '<strong>$1</strong>')
        .replace(/^- (.+)$/gm, '<li>$1</li>')
        .replace(/(<li>.+<\/li>)+/g, '<ul>$&</ul>')
        .replace(/!\[([^\]]*)\]\((file:\/\/\/([^)]+))\)/g, (match, alt, uri, filePath) => {
            const absolutePath = filePath.replace(/^\/+/, ''); // Fix path for Windows
            if (fs.existsSync(absolutePath)) {
                const base64 = fs.readFileSync(absolutePath).toString('base64');
                return `<img src="data:image/png;base64,${base64}" alt="${alt}" style="max-width: 100%; border-radius: 12px; box-shadow: 0 8px 30px rgba(0,0,0,0.12); margin: 20px 0;">`;
            }
            return `<p style="color: red;">Image not found: ${absolutePath}</p>`;
        })
        .replace(/^> \[!NOTE\]\s*\n> (.+)$/gm, '<div class="note"><strong>Note:</strong> $1</div>')
        .replace(/\| (.+) \| (.+) \|/g, '<tr><td>$1</td><td>$2</td></tr>')
        .replace(/(<tr>.+<\/tr>)+/g, '<table border="1">$&</table>')
        .replace(/---/g, '<hr>')
        .replace(/```bash\n([\s\S]+?)\n```/g, '<pre><code>$1</code></pre>');

    const html = `
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <style>
            @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap');
            body { 
                font-family: 'Inter', -apple-system, sans-serif; 
                line-height: 1.6; 
                color: #1a1a1a; 
                max-width: 900px; 
                margin: 0 auto; 
                padding: 40px;
                background: #fff;
            }
            h1 { font-size: 32px; color: #000; border-bottom: 2px solid #eaeaea; padding-bottom: 10px; margin-top: 40px; }
            h2 { font-size: 24px; color: #333; margin-top: 30px; border-left: 4px solid #000; padding-left: 15px; }
            h3 { font-size: 18px; color: #444; margin-top: 20px; }
            ul { padding-left: 20px; }
            li { margin-bottom: 8px; }
            pre { background: #f4f4f4; padding: 15px; border-radius: 8px; font-family: 'Courier New', monospace; overflow-x: auto; font-size: 14px; }
            table { width: 100%; border-collapse: collapse; margin: 20px 0; border: none; }
            th, td { padding: 12px; text-align: left; border-bottom: 1px solid #efefef; }
            tr:first-child td { font-weight: 700; background: #f9f9f9; }
            hr { border: 0; border-top: 1px solid #eee; margin: 40px 0; }
            .note { background: #f0f7ff; border-left: 4px solid #007bff; padding: 15px; border-radius: 0 8px 8px 0; margin: 20px 0; }
            img { display: block; margin: 30px auto; }
            @media print {
                body { padding: 0; }
                .page-break { page-break-before: always; }
            }
        </style>
    </head>
    <body>
        ${htmlContent}
    </body>
    </html>
    `;

    console.log('Launching Puppeteer...');
    const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox'] });
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'networkidle0' });

    console.log('Generating PDF...');
    await page.pdf({
        path: OUTPUT_PATH,
        format: 'A4',
        printBackground: true,
        margin: { top: '20mm', right: '20mm', bottom: '20mm', left: '20mm' }
    });

    await browser.close();
    console.log('PDF Successfully Saved to:', OUTPUT_PATH);
}

generatePDF().catch(console.error);

import puppeteer from 'puppeteer';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const imgDir = path.join(process.env.USERPROFILE, '.gemini', 'antigravity', 'brain', 'a704a5c3-f914-449b-be94-a461679971f2');
const htmlPath = path.resolve(__dirname, 'docs', 'documentation.html');
const outputPath = path.resolve(__dirname, 'HMS_Documentation.pdf');

let html = fs.readFileSync(htmlPath, 'utf8');

// Replace all IMG_DIR/filename.png references with base64 data URIs
html = html.replace(/IMG_DIR\/([^"]+\.png)/g, (match, filename) => {
  const imgPath = path.join(imgDir, filename);
  if (fs.existsSync(imgPath)) {
    const base64 = fs.readFileSync(imgPath).toString('base64');
    console.log('Embedded: ' + filename);
    return `data:image/png;base64,${base64}`;
  } else {
    console.warn('Image not found: ' + imgPath);
    return match;
  }
});

console.log('Launching browser...');
const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage();

await page.setContent(html, { waitUntil: 'networkidle0', timeout: 60000 });

await page.pdf({
  path: outputPath,
  format: 'A4',
  printBackground: true,
  margin: { top: '0', right: '0', bottom: '0', left: '0' },
  displayHeaderFooter: false,
});

await browser.close();
console.log('PDF generated successfully: ' + outputPath);

import puppeteer from 'puppeteer';
import fs from 'fs';
import path from 'path';

const DOC_PATH = 'c:/Users/asifk/Documents/antigravity/HMS/docs/app_manual.md';
const OUTPUT_PATH = 'c:/Users/asifk/Documents/antigravity/HMS/HMS_Professional_Documentation.pdf';

async function generatePDF() {
    console.log('Reading documentation...');
    let markdown = fs.readFileSync(DOC_PATH, 'utf8');

    // Simple Table Parser
    const parseTable = (markdown) => {
        const lines = markdown.split('\n');
        let html = '';
        let inTable = false;
        let tableHeader = true;

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (line.startsWith('|') && line.endsWith('|')) {
                if (!inTable) {
                    html += '<table>';
                    inTable = true;
                    tableHeader = true;
                }
                if (line.includes('---')) continue; // Skip separator line

                const cells = line.split('|').filter(c => c !== '').map(c => c.trim());
                html += '<tr>';
                cells.forEach(cell => {
                    const tag = tableHeader ? 'th' : 'td';
                    html += `<${tag}>${cell}</${tag}>`;
                });
                html += '</tr>';
                tableHeader = false;
            } else {
                if (inTable) {
                    html += '</table>';
                    inTable = false;
                }
                html += line + '\n';
            }
        }
        return html;
    };

    let processedContent = parseTable(markdown);

    // Generate TOC
    const headers = [];
    const headerRegex = /^(#{1,3}) (.+)$/gm;
    let match;
    while ((match = headerRegex.exec(markdown)) !== null) {
        headers.push({
            level: match[1].length,
            title: match[2],
            id: match[2].toLowerCase().replace(/[^\w]+/g, '-')
        });
    }

    let tocHtml = '<div class="toc-page"><h1>Table of Contents</h1><ul>';
    headers.forEach(header => {
        if (header.level === 1 && header.title.includes('Manual')) return; // Skip main title in TOC
        tocHtml += `<li class="toc-level-${header.level}"><a href="#${header.id}">${header.title}</a></li>`;
    });
    tocHtml += '</ul></div>';

    // Enhanced Markdown to HTML converter
    let htmlContent = processedContent
        .replace(/^# (.+)$/gm, (m, title) => `<h1 id="${title.toLowerCase().replace(/[^\w]+/g, '-')}">${title}</h1>`)
        .replace(/^## (.+)$/gm, (m, title) => `<h2 id="${title.toLowerCase().replace(/[^\w]+/g, '-')}">${title}</h2>`)
        .replace(/^### (.+)$/gm, (m, title) => `<h3 id="${title.toLowerCase().replace(/[^\w]+/g, '-')}">${title}</h3>`)
        .replace(/^\*\*([^*]+)\*\*/gm, '<strong>$1</strong>')
        .replace(/^- (.+)$/gm, '<li>$1</li>')
        .replace(/(<li>.+<\/li>)+/g, '<ul>$&</ul>')
        .replace(/!\[([^\]]*)\]\((file:\/\/\/([^)]+))\)/g, (match, alt, uri, filePath) => {
            const winPath = filePath.startsWith('c:/') ? filePath.replace('c:/', 'C:/') : filePath;
            if (fs.existsSync(winPath)) {
                const base64 = fs.readFileSync(winPath).toString('base64');
                return `<img src="data:image/png;base64,${base64}" alt="${alt}" class="embedded-image">`;
            }
            return `<p style="color: red;">Image not found: ${winPath}</p>`;
        })
        .replace(/^> \[!NOTE\]\s*\n> (.+)$/gm, '<div class="note"><strong>Note:</strong> $1</div>')
        .replace('[[TOC]]', tocHtml);

    const html = `
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <style>
            @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap');

            :root {
                --primary: #0070f3;
                --text: #171717;
                --text-muted: #666;
                --border: #eaeaea;
                --bg: #ffffff;
            }

            body { 
                font-family: 'Outfit', sans-serif; 
                line-height: 1.3; 
                color: var(--text); 
                max-width: 900px; 
                margin: 0 auto; 
                padding: 0;
            }

            /* Cover Page */
            .cover-page {
                height: 290mm;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                text-align: center;
                background: linear-gradient(135deg, #f6f9fc 0%, #eef2f7 100%);
                page-break-after: always;
                margin: 0;
            }

            .cover-title { font-size: 64px; font-weight: 700; margin: 0; background: linear-gradient(to right, #0070f3, #00dfd8); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
            .cover-subtitle { font-size: 20px; color: var(--text-muted); margin: 10px 0 40px 0; }

            /* TOC */
            .toc-page { padding: 20px 0; page-break-after: always; }
            .toc-page h1 { font-size: 24px; margin-bottom: 20px; border-bottom: 2px solid var(--border); }
            .toc-page ul { list-style: none; padding: 0; }
            .toc-page li { margin-bottom: 5px; }
            .toc-page a { text-decoration: none; color: var(--text); font-size: 14px; }
            .toc-level-1 { font-weight: 700; margin-top: 10px; }
            .toc-level-2 { margin-left: 15px; border-bottom: 1px dotted var(--border); display: block; font-weight: 600; }
            .toc-level-3 { margin-left: 30px; border-bottom: 1px dotted var(--border); display: block; font-size: 13px; color: var(--text-muted); }

            /* Content */
            h1 { font-size: 28px; margin: 20px 0 10px 0; border-bottom: 2px solid var(--primary); padding-bottom: 5px; }
            h2 { font-size: 22px; margin: 15px 0 8px 0; color: var(--primary); }
            h3 { font-size: 16px; margin: 12px 0 6px 0; }

            p { margin: 0 0 10px 0; }
            ul { margin: 0 0 10px 0; padding-left: 20px; }
            li { margin-bottom: 3px; }

            /* Tables */
            table { width: 100%; border-collapse: collapse; margin: 15px 0; font-size: 13px; table-layout: fixed; }
            th { background: #f6f9fc; color: var(--primary); font-weight: 700; text-align: left; padding: 10px; border: 1px solid var(--border); }
            td { padding: 8px; border: 1px solid var(--border); vertical-align: middle; word-wrap: break-word; }
            tr:nth-child(even) { background: #fafafa; }

            .embedded-image { max-width: 100%; height: auto; border-radius: 4px; border: 1px solid var(--border); display: block; margin-bottom: 25px; }
            td .embedded-image { max-height: 120px; margin: 0 auto; margin-bottom: 0; }

            .note { background: #f0f7ff; border-left: 5px solid var(--primary); padding: 10px; border-radius: 0 4px 4px 0; margin: 15px 0; font-size: 13px; }

            @media print {
                html, body { height: 100%; margin: 0 !important; padding: 0 !important; }
                .main-content { padding: 15mm; }
                h1, h2, h3 { page-break-after: avoid; }
                tr { page-break-inside: avoid; }
                img { page-break-inside: avoid; }
            }
        </style>
    </head>
    <body>
        <div class="cover-page">
            <h1 class="cover-title">HMS Elite</h1>
            <p class="cover-subtitle">Hospital Management System<br>Technical Documentation & User Manual</p>
            <div style="margin: 20px 0;">
                <svg width="60" height="60" viewBox="0 0 100 100">
                    <circle cx="50" cy="50" r="45" fill="none" stroke="#0070f3" stroke-width="2" />
                    <path d="M30 50 L70 50 M50 30 L50 70" stroke="#0070f3" stroke-width="8" stroke-linecap="round" />
                </svg>
            </div>
            <div style="margin-top: 30px; color: var(--text-muted); font-size: 12px;">
                <p><strong>Prepared for:</strong> Team Lead</p>
                <p><strong>Version:</strong> 1.0.0 | March 2026</p>
            </div>
        </div>

        <div class="main-content">
            ${htmlContent}
        </div>
    </body>
    </html>
    `;

    console.log('Launching Puppeteer...');
    const browser = await puppeteer.launch({ headless: true });
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'networkidle0' });

    console.log('Generating PDF...');
    await page.pdf({
        path: OUTPUT_PATH,
        format: 'A4',
        printBackground: true,
        margin: { top: '0', right: '0', bottom: '0', left: '0' }, // Margins are handled in CSS
        displayHeaderFooter: true,
        headerTemplate: '<span></span>', // No header to save space
        footerTemplate: '<div style="font-size: 8px; color: #999; margin-left: auto; margin-right: 15mm; font-family: sans-serif;"><span class="pageNumber"></span> / <span class="totalPages"></span></div>'
    });

    await browser.close();
    console.log('Zero-Whitespace PDF Successfully Saved to:', OUTPUT_PATH);
}

generatePDF().catch(console.error);

import puppeteer from 'puppeteer';
import fs from 'fs';
import path from 'path';
import { marked } from 'marked';

async function generatePresentationPdf() {
    const markdownPath = path.join(process.cwd(), 'docs', 'presentation_guide.md');
    const outputPath = path.join(process.cwd(), 'HMS_Presentation_Preparation.pdf');

    console.log('Reading presentation guide...');
    const markdown = fs.readFileSync(markdownPath, 'utf8');
    const htmlContent = marked(markdown);

    const fullHtml = `
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="UTF-8">
        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
        <style>
            body { 
                font-family: 'Inter', sans-serif; 
                line-height: 1.6; 
                color: #171717; 
                max-width: 800px; 
                margin: 0 auto; 
                padding: 40px;
                background: #fff;
            }
            h1 { color: #0070f3; font-size: 32px; border-bottom: 2px solid #eaeaea; padding-bottom: 10px; margin-bottom: 30px; }
            h2 { color: #0070f3; font-size: 24px; margin-top: 40px; }
            h3 { color: #444; font-size: 18px; margin-top: 30px; border-left: 4px solid #0070f3; padding-left: 15px; }
            hr { border: 0; border-top: 1px solid #eaeaea; margin: 40px 0; }
            code { background: #f4f4f4; padding: 2px 5px; border-radius: 4px; font-family: monospace; }
            strong { color: #000; }
            ul { padding-left: 20px; }
            li { margin-bottom: 10px; }
            blockquote { 
                background: #f9f9f9; 
                border-left: 5px solid #ccc; 
                margin: 1.5em 10px; 
                padding: 0.5em 10px; 
            }
            .speak-block {
                background: #f0f7ff;
                padding: 15px;
                border-radius: 8px;
                border: 1px solid #0070f3;
                margin: 20px 0;
            }
        </style>
    </head>
    <body>
        ${htmlContent.replace(/<strong>Speak this:<\/strong>/g, '<div class="speak-block"><strong>Speak this:</strong>')}
    </body>
    </html>
    `;

    console.log('Launching Puppeteer...');
    const browser = await puppeteer.launch({ headless: true });
    const page = await browser.newPage();
    await page.setContent(fullHtml, { waitUntil: 'networkidle0' });

    console.log('Generating PDF...');
    await page.pdf({
        path: outputPath,
        format: 'A4',
        margin: { top: '20mm', right: '20mm', bottom: '20mm', left: '20mm' },
        printBackground: true
    });

    await browser.close();
    console.log('PDF saved to HMS_Presentation_Preparation.pdf');
}

generatePresentationPdf().catch(console.error);

import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import { useNavigate } from 'react-router-dom';

const Navbar = ({ onToggleSidebar }) => {
  const { theme, toggleTheme, showToast } = useApp();
  const [search, setSearch] = useState('');

  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();
    if (search.trim()) {
      const query = search.trim().toLowerCase();

      // Keyword to Route Mapping
      const modules = {
        'patient': '/patients',
        'appoint': '/appointments',
        'sched': '/appointments',
        'emr': '/emr', 'ehr': '/emr',
        'bill': '/billing', 'rev': '/billing',
        'pharm': '/pharmacy', 'med': '/pharmacy',
        'lab': '/lab', 'test': '/lab', 'diag': '/lab',
        'bed': '/beds',
        'staff': '/staff', 'doc': '/staff', 'nurse': '/staff',
        'invent': '/inventory', 'stock': '/inventory',
        'blood': '/bloodbank',
        'rep': '/reports', 'analy': '/reports',
        'dash': '/'
      };

      const match = Object.keys(modules).find(key => query.includes(key));
      if (match) {
        navigate(modules[match]);
      } else {
        // Default: Search for specific patient name/ID
        navigate(`/patients?search=${encodeURIComponent(search.trim())}`);
      }
      setSearch('');
    }
  };

  return (
    <header className="navbar fixed-top w-100" style={{ left: 'var(--sidebar-w)', width: 'calc(100% - var(--sidebar-w))' }}>
      <div className="container-fluid px-3 px-md-4 h-100 d-flex align-items-center">
        {/* Hamburger menu - visible on mobile/tablet */}
        <button className="navbar-hamburger" onClick={onToggleSidebar} aria-label="Open menu">
          <i className="bi bi-list" style={{ fontSize: '1.25rem' }} aria-hidden="true"></i>
        </button>

        {/* Search Bar */}
        <form onSubmit={handleSearch} className="d-flex align-items-center flex-grow-1" style={{ maxWidth: '420px' }}>
          <div className="position-relative w-100">
            <i className="bi bi-search position-absolute" style={{ left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--accents-5)', fontSize: '0.85rem' }} aria-hidden="true"></i>
            <input
              type="text"
              className="form-control"
              placeholder="Search patients, records, modules…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{ 
                paddingLeft: '36px',
                height: '38px',
                fontSize: '0.85rem',
                background: 'var(--accents-1)',
                border: '1px solid var(--accents-2)',
                color: 'var(--geist-foreground)',
                borderRadius: '8px'
              }}
              id="navbar-search"
            />
          </div>
        </form>

        {/* Right side actions */}
        <div className="d-flex align-items-center gap-2 ms-auto">
          {/* Dark Mode Toggle */}
          <button
            className="btn d-flex align-items-center justify-content-center"
            onClick={toggleTheme}
            title={theme === 'light' ? 'Switch to Dark Mode' : 'Switch to Light Mode'}
            aria-label="Toggle theme"
            style={{ 
              width: '38px', 
              height: '38px', 
              borderRadius: '8px',
              padding: 0,
              border: '1px solid var(--accents-2)',
              background: 'var(--accents-1)',
              color: 'var(--geist-foreground)',
              transition: 'all 0.2s ease'
            }}
          >
            <i className={`bi ${theme === 'light' ? 'bi-moon-stars-fill' : 'bi-sun-fill'}`} style={{ fontSize: '1rem', color: 'var(--geist-foreground)' }} aria-hidden="true"></i>
          </button>
        </div>
      </div>
    </header>
  );
};

