import React, { createContext, useContext, useEffect, useState } from 'react';
import { authApi } from '../lib/api';

const AppContext = createContext();

const formatDate = (value, options = { day: '2-digit', month: 'short', year: 'numeric' }) => {
  if (!value) {
    return '-';
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat('en-GB', options).format(parsed);
};

const formatTime = (value) => {
  if (!value) {
    return '-';
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  }).format(parsed);
};

const formatCurrency = (amount) =>
  new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(Number(amount || 0));

const toIsoDate = (value) => {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return new Date().toISOString().slice(0, 10);
  }
  return parsed.toISOString().slice(0, 10);
};

export const parseDisplayMonth = (value) => {
  const parsed = new Date(`01 ${value}`);
  if (Number.isNaN(parsed.getTime())) {
    const fallback = new Date();
    fallback.setMonth(fallback.getMonth() + 12);
    return fallback.toISOString().slice(0, 10);
  }
  return parsed.toISOString().slice(0, 10);
};

export const parseDisplayTime = (value) => {
  if (!value) {
    return new Date().toISOString();
  }

  const match = value.trim().match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?$/i);
  const now = new Date();
  if (!match) {
    return now.toISOString();
  }

  let hours = Number(match[1]);
  const minutes = Number(match[2]);
  const meridiem = match[3]?.toUpperCase();

  if (meridiem && hours <= 12) {
    if (meridiem === 'PM' && hours !== 12) {
      hours += 12;
    }
    if (meridiem === 'AM' && hours === 12) {
      hours = 0;
    }
  }

  const parsed = new Date(now);
  parsed.setHours(Math.min(hours, 23), minutes, 0, 0);
  return parsed.toISOString();
};

export const createCode = (prefix) => `${prefix}-${Date.now().toString().slice(-6)}`;

export const mapPatientFromApi = (patient) => ({
  id: patient.patient_code,
  apiId: patient.id,
  name: patient.name,
  age: patient.age,
  gender: patient.gender,
  bloodGroup: patient.blood_group,
  lastVisit: formatDate(patient.last_visit),
  status: patient.status,
});

export const mapAppointmentFromApi = (appointment) => ({
  id: appointment.appointment_code,
  apiId: appointment.id,
  time: formatTime(appointment.scheduled_time),
  patient: appointment.patient_name,
  doctor: appointment.doctor_name,
  type: appointment.appointment_type,
  status: appointment.status,
});

export const mapRecordFromApi = (record) => ({
  id: record.record_code,
  apiId: record.id,
  clinicalId: record.clinical_id,
  date: formatDate(record.record_date),
  patient: record.patient_name,
  doctor: record.doctor_name,
  diagnosis: record.diagnosis,
  prescription: record.prescription,
});

export const mapInvoiceFromApi = (invoice) => ({
  id: invoice.invoice_code,
  apiId: invoice.id,
  patient: invoice.patient_name,
  date: formatDate(invoice.invoice_date),
  amount: formatCurrency(invoice.amount),
  amountValue: Number(invoice.amount),
  status: invoice.status,
  method: invoice.payment_method,
});

export const mapMedicineFromApi = (medicine) => ({
  id: medicine.medicine_code,
  apiId: medicine.id,
  name: medicine.name,
  batch: medicine.batch,
  stock: medicine.stock,
  expiry: formatDate(medicine.expiry_date, { month: 'short', year: 'numeric' }),
  status: medicine.status,
});

export const mapTestFromApi = (test) => ({
  id: test.test_code,
  apiId: test.id,
  patient: test.patient_name,
  test: test.test_name,
  doctor: test.doctor_name,
  status: test.status,
});

export const mapStaffFromApi = (staffMember) => ({
  id: staffMember.staff_code,
  apiId: staffMember.id,
  name: staffMember.name,
  role: staffMember.role,
  dept: staffMember.department,
  shift: staffMember.shift,
  status: staffMember.status,
});

export const mapBedFromApi = (bed) => ({
  id: bed.bed_number,
  apiId: bed.id,
  ward: bed.ward_name,
  type: bed.type,
  status: bed.status,
});

export const mapBloodGroupFromApi = (bg) => ({
  id: bg.blood_group,
  apiId: bg.id,
  type: bg.blood_group,
  units: bg.units,
  status: bg.status,
  trend: bg.trend,
});

export const mapActivityFromApi = (act) => ({
  id: act.id,
  apiId: act.id,
  type: act.type,
  group: act.blood_group,
  units: act.units,
  donor: act.donor_name,
  hospital: act.donor_name,
  date: act.date,
});

export const mapInventoryFromApi = (inv) => ({
  id: inv.item_code,
  apiId: inv.id,
  name: inv.name,
  category: inv.category,
  stock: inv.stock,
  unit: inv.unit,
  status: inv.status,
});

export const AppProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    try {
      const savedUser = sessionStorage.getItem('hms_user_data');
      if (savedUser) {
        return JSON.parse(savedUser);
      }
      return null;
    } catch {
      return null;
    }
  });

  const [notifications, setNotifications] = useState([]);
  const [theme, setTheme] = useState(() => localStorage.getItem('hms_theme') || 'light');
  const [isAppLoading, setIsAppLoading] = useState(true);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('hms_theme', theme);
  }, [theme]);

  useEffect(() => {
    let active = true;

    if (!user?.id) {
      setIsAppLoading(false);
      return () => {
        active = false;
      };
    }

    setIsAppLoading(true);

    const checkAuth = async () => {
      // Simulate quick auth check
      setTimeout(() => {
        if (active) {
          setIsAppLoading(false);
        }
      }, 300);
    };

    checkAuth();

    return () => {
      active = false;
    };
  }, [user]);

  const toggleTheme = () => setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));

  const persistUser = (apiUser, token) => {
    const normalizedUser = {
      id: apiUser.id,
      name: apiUser.full_name,
      username: apiUser.username,
      email: apiUser.email,
      role: apiUser.role,
    };
    // Store the signed JWT for use in Authorization: Bearer headers
    sessionStorage.setItem('hms_token', token);
    sessionStorage.setItem('hms_user_data', JSON.stringify(normalizedUser));
    setUser(normalizedUser);
    return normalizedUser;
  };

  const login = async (username, password) => {
    const response = await authApi.login({ username, password });
    return persistUser(response.user, response.token);
  };

  const signup = async ({ fullName, username, email, password, role }) => {
    const response = await authApi.signup({
      full_name: fullName,
      username,
      email,
      password,
      role,
    });
    return persistUser(response.user, response.token);
  };

  const logout = () => {
    setUser(null);
    sessionStorage.removeItem('hms_token');
    sessionStorage.removeItem('hms_user_data');
  };

  const showToast = React.useCallback((message, type = 'info') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  }, []);

  const value = {
    user,
    setUser,
    login,
    signup,
    logout,
    theme,
    setTheme,
    toggleTheme,
    notifications,
    setNotifications,
    toast,
    showToast,
    isAppLoading,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useApp, mapBloodGroupFromApi, mapActivityFromApi } from '../context/AppContext';
import { useCrud } from '../hooks/useCrud';
import { bloodInventoryApi, bloodActivitiesApi } from '../lib/api';
import Modal from '../components/UI/Modal';
import EmptyState from '../components/UI/EmptyState';
import DeleteConfirmation from '../components/UI/DeleteConfirmation';

const BloodBank = () => {
  const { showToast } = useApp();
  const { 
    data: bloodGroups, 
    loading: loadingInventory,
    loadData: loadBlood,
    updateData: updateInventory,
    removeData: deleteInventory
  } = useCrud(bloodInventoryApi, mapBloodGroupFromApi);

  const { 
    data: activities, 
    loading: loadingActivities,
    addData: addActivity,
    updateData: updateActivity,
    removeData: deleteActivity
  } = useCrud(bloodActivitiesApi, mapActivityFromApi);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isActivityEditModalOpen, setIsActivityEditModalOpen] = useState(false);
  const [isInventoryEditModalOpen, setIsInventoryEditModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);

  const [editingActivity, setEditingActivity] = useState(null);
  const [editingInventory, setEditingInventory] = useState(null);
  const [deletingItem, setDeletingItem] = useState(null);
  const [deletingType, setDeletingType] = useState(''); // 'inventory' or 'activity'

  const [formData, setFormData] = useState({
    type: 'Donation',
    blood_group: 'O+',
    units: '',
    donor_name: ''
  });

  const [activityEditFormData, setActivityEditFormData] = useState({
    type: 'Donation',
    blood_group: 'O+',
    units: '',
    donor_name: ''
  });

  const [inventoryEditFormData, setInventoryEditFormData] = useState({
    units: '',
    status: 'Stable',
    trend: 'Stable'
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.units) {
      showToast('Please enter the number of units.', 'warning');
      return;
    }
    try {
      await addActivity(formData);
      showToast(`Blood ${formData.type.toLowerCase()} logged successfully.`);
      setIsModalOpen(false);
      setFormData({ type: 'Donation', blood_group: 'O+', units: '', donor_name: '' });
      await loadBlood(); // refresh totals
    } catch (error) {
      showToast(error.message || 'Unable to log activity.', 'error');
    }
  };

  const openActivityEditModal = (act) => {
    setEditingActivity(act);
    setActivityEditFormData({
      type: act.type,
      blood_group: act.group,
      units: act.units,
      donor_name: act.donor || act.hospital || ''
    });
    setIsActivityEditModalOpen(true);
  };

  const handleActivityEditSubmit = async (e) => {
    e.preventDefault();
    try {
      await updateActivity(editingActivity.apiId, activityEditFormData);
      showToast('Activity log updated.');
      setIsActivityEditModalOpen(false);
      setEditingActivity(null);
      loadBlood(); // refresh totals in case units changed
    } catch (error) {
      showToast(error.message || 'Unable to update activity.', 'error');
    }
  };

  const openInventoryEditModal = (group) => {
    setEditingInventory(group);
    setInventoryEditFormData({
      units: group.units,
      status: group.status,
      trend: group.trend
    });
    setIsInventoryEditModalOpen(true);
  };

  const handleInventoryEditSubmit = async (e) => {
    e.preventDefault();
    try {
      await updateInventory(editingInventory.apiId, {
        units: parseInt(inventoryEditFormData.units, 10),
        status: inventoryEditFormData.status,
        trend: inventoryEditFormData.trend
      });
      showToast(`Inventory for ${editingInventory.type} updated.`);
      setIsInventoryEditModalOpen(false);
      setEditingInventory(null);
    } catch (error) {
      showToast(error.message || 'Unable to update inventory.', 'error');
    }
  };

  const handleDelete = async () => {
    try {
      if (deletingType === 'activity') {
        await deleteActivity(deletingItem.apiId);
        showToast('Activity record removed.');
        loadBlood();
      } else {
        await deleteInventory(deletingItem.apiId);
        showToast(`Inventory record for ${deletingItem.type} removed.`);
      }
      setIsDeleteModalOpen(false);
      setDeletingItem(null);
    } catch (error) {
      showToast(error.message || 'Unable to delete record.', 'error');
    }
  };

  return (
    <main className="bloodbank-page p-4">
      <div className="d-flex justify-content-between align-items-center mb-5">
        <div>
          <h2 className="fw-bold mb-1">Blood Bank Repository</h2>
          <p className="text-muted mb-0">Monitor real-time blood unit availability and donation cycle.</p>
        </div>
        <div className="d-flex gap-2">
          <button 
            className="btn btn-glass px-4 py-2 border d-flex align-items-center"
            onClick={async () => {
              try {
                const { jsPDF } = await import('jspdf');
                const { default: autoTable } = await import('jspdf-autotable');
                const doc = new jsPDF();

                doc.setFontSize(22);
                doc.setTextColor(180, 0, 0);
                doc.text('HMS ELITE — BLOOD BANK REGISTRY', 14, 22);

                doc.setFontSize(10);
                doc.setTextColor(100);
                doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 30);
                doc.setDrawColor(180, 0, 0);
                doc.line(14, 34, 196, 34);

                // Blood inventory summary
                doc.setFontSize(13);
                doc.setTextColor(40);
                doc.text('Blood Group Inventory', 14, 43);

                if (bloodGroups.length > 0) {
                  autoTable(doc, {
                    startY: 48,
                    head: [['Blood Group', 'Units Available', 'Trend', 'Status']],
                    body: bloodGroups.map(g => [g.type, String(g.units), g.trend, g.status]),
                    theme: 'striped',
                    headStyles: { fillColor: [180, 0, 0] },
                  });
                } else {
                  doc.setFontSize(10);
                  doc.setTextColor(150);
                  doc.text('No blood inventory data.', 14, 55);
                }

                // Activity log
                const nextY = doc.lastAutoTable ? doc.lastAutoTable.finalY + 15 : 70;
                doc.setFontSize(13);
                doc.setTextColor(40);
                doc.text('Activity Log', 14, nextY);

                if (activities.length > 0) {
                  autoTable(doc, {
                    startY: nextY + 5,
                    head: [['Type', 'Blood Group', 'Units', 'Donor / Entity', 'Date']],
                    body: activities.map(a => [
                      a.type, a.group, String(a.units),
                      a.donor || a.hospital || '—', a.date
                    ]),
                    theme: 'grid',
                    headStyles: { fillColor: [60, 60, 60] },
                  });
                } else {
                  doc.setFontSize(10);
                  doc.setTextColor(150);
                  doc.text('No activity records found.', 14, nextY + 10);
                }

                doc.save('HMS_BloodBank_Registry.pdf');
                showToast('✓ Blood Bank Registry downloaded!');
              } catch (err) {
                console.error('PDF export failed:', err);
                showToast('PDF generation failed. Please try again.', 'error');
              }
            }}
          >
            <i className="bi bi-file-earmark-medical me-2" aria-hidden="true"></i>
            Request Registry
          </button>
          <button 
            className="btn btn-primary px-4 py-2 d-flex align-items-center"
            onClick={() => { setFormData({...formData, type: 'Donation'}); setIsModalOpen(true); }}
          >
            <i className="bi bi-person-plus me-2" aria-hidden="true"></i>
            Add Donor
          </button>
        </div>
      </div>

      <div className="row g-4 mb-5">
        {loadingInventory ? (
          <div className="col-12 text-center py-5">
            <div className="spinner-border text-danger" role="status">
              <span className="visually-hidden">Loading Inventory...</span>
            </div>
          </div>
        ) : [
          'A+', 'A-', 'B+', 'B-', 'O+', 'O-', 'AB+', 'AB-'
        ].map(type => {
          const group = bloodGroups.find(g => g.type === type) || { 
            type, units: 0, status: 'Empty', trend: 'Stable' 
          };
          return (
            <div key={type} className="col-md-3">
              <div className="glass-card p-4 transition-all hover-translate-y position-relative h-100">
                <div className="d-flex justify-content-between align-items-start mb-3">
                  <div 
                    className="rounded-circle d-flex align-items-center justify-content-center fw-bold text-white shadow-sm" 
                    style={{ 
                      width: '48px', 
                      height: '48px', 
                      fontSize: '1.25rem',
                      background: 'linear-gradient(135deg, #ee0000 0%, #a00000 100%)'
                    }}
                  >
                    {type}
                  </div>
                  <div className="d-flex align-items-center gap-2">
                    <span 
                      className="px-2 py-1 rounded-pill small fw-bold"
                      style={{ 
                        fontSize: '0.65rem',
                        background: group.status === 'Stable' ? 'rgba(0, 112, 243, 0.1)' : 
                                   group.status === 'Low' ? 'rgba(245, 166, 35, 0.1)' : 'rgba(238, 0, 0, 0.1)',
                        color: group.status === 'Stable' ? 'var(--geist-success)' : 
                               group.status === 'Low' ? 'var(--geist-warning)' : 'var(--geist-error)',
                      }}
                    >
                      {group.status.toUpperCase()}
                    </span>
                    {group.apiId && (
                      <div className="dropdown">
                        <button className="btn btn-sm btn-glass p-0 border-0" data-bs-toggle="dropdown" style={{ width: '20px' }}>
                          <i className="bi bi-three-dots-vertical small"></i>
                        </button>
                        <ul className="dropdown-menu dropdown-menu-end glass-card border shadow-sm">
                          <li><button className="dropdown-item small" onClick={() => openInventoryEditModal(group)}><i className="bi bi-pencil me-2"></i>Edit Stock</button></li>
                          <li><button className="dropdown-item small text-danger" onClick={() => {
                            setDeletingItem(group);
                            setDeletingType('inventory');
                            setIsDeleteModalOpen(true);
                          }}><i className="bi bi-trash me-2"></i>Remove</button></li>
                        </ul>
                      </div>
                    )}
                  </div>
                </div>
                <h3 className="fw-bold mb-1" style={{ fontVariantNumeric: 'tabular-nums' }}>{group.units} Units</h3>
                <p className="small text-muted mb-0">Stock Trend: <span className={group.trend?.includes('+') ? 'text-success' : 'text-danger'}>{group.trend}</span> today</p>
                {group.units === 0 && <div className="text-warning small mt-2"><i className="bi bi-exclamation-triangle me-1"></i>Inventory Empty</div>}
              </div>
            </div>
          );
        })}
      </div>

      <div className="glass-card p-4">
        <h5 className="fw-bold mb-4">Recent Activity Logs</h5>
        <div className="table-responsive">
          <table className="table">
            <thead>
              <tr>
                <th>Type</th>
                <th>Group</th>
                <th>Units</th>
                <th>Entity/Person</th>
                <th>Timestamp</th>
                <th className="text-end">Actions</th>
              </tr>
            </thead>
            <tbody>
              {activities.length === 0 ? (
                <tr>
                   <td colSpan="6" className="p-0">
                      <EmptyState 
                        icon="bi-journal-text"
                        title="No Activity"
                        description="No donation or usage cycles have been logged yet."
                      />
                   </td>
                </tr>
              ) : activities.map((act) => (
                <tr key={act.id}>
                  <td>
                    <span className={`fw-medium ${act.type === 'Donation' ? 'text-success' : 'text-primary'}`}>
                      {act.type}
                    </span>
                  </td>
                  <td className="fw-bold">{act.group}</td>
                  <td style={{ fontVariantNumeric: 'tabular-nums' }}>{act.units}</td>
                  <td className="text-muted">{act.donor || act.hospital}</td>
                  <td className="small text-muted">{act.date}</td>
                  <td className="text-end">
                    <button className="btn btn-sm btn-glass me-2" onClick={() => openActivityEditModal(act)}>
                      <i className="bi bi-pencil"></i>
                    </button>
                    <button className="btn btn-sm btn-glass text-danger" onClick={() => {
                      setDeletingItem(act);
                      setDeletingType('activity');
                      setIsDeleteModalOpen(true);
                    }}>
                      <i className="bi bi-trash"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Log Activity Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Log Blood Bank Activity">
        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="blood-activity-type" className="form-label text-muted fw-bold small text-uppercase mb-2">Activity Type</label>
            <select 
              id="blood-activity-type"
              className="form-select" 
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value})}
            >
              <option>Donation</option>
              <option>Usage</option>
              <option>Transfer</option>
            </select>
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="blood-group" className="form-label text-muted fw-bold small text-uppercase mb-2">Blood Group</label>
              <select 
                id="blood-group"
                className="form-select"
                value={formData.blood_group}
                onChange={e => setFormData({...formData, blood_group: e.target.value})}
              >
                <option>A+</option><option>A-</option>
                <option>B+</option><option>B-</option>
                <option>O+</option><option>O-</option>
                <option>AB+</option><option>AB-</option>
              </select>
            </div>
            <div className="col-md-6">
              <label htmlFor="blood-units" className="form-label text-muted fw-bold small text-uppercase mb-2">Units (Bags)</label>
              <input 
                id="blood-units"
                type="number" 
                className="form-control" 
                placeholder="1" 
                min="1"
                value={formData.units}
                onChange={e => setFormData({...formData, units: e.target.value})}
                required
              />
            </div>
          </div>
          <div className="mb-4">
            <label htmlFor="blood-donor-name" className="form-label text-muted fw-bold small text-uppercase mb-2">Entity or Donor Name</label>
            <input 
              id="blood-donor-name"
              type="text" 
              className="form-control" 
              placeholder="e.g. John Doe / City Hospital" 
              value={formData.donor_name}
              onChange={e => setFormData({...formData, donor_name: e.target.value})}
              required
            />
          </div>
          <div className="d-flex gap-2 mt-5">
            <button type="button" className="btn btn-glass w-100 py-2" onClick={() => setIsModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary w-100 py-2">Log Activity</button>
          </div>
        </form>
      </Modal>

      {/* Edit Activity Modal */}
      <Modal isOpen={isActivityEditModalOpen} onClose={() => setIsActivityEditModalOpen(false)} title="Edit Activity Record">
        <form onSubmit={handleActivityEditSubmit}>
          <div className="mb-4">
            <label htmlFor="edit-activity-type" className="form-label text-muted fw-bold small text-uppercase mb-2">Activity Type</label>
            <select 
              id="edit-activity-type"
              className="form-select" 
              value={activityEditFormData.type}
              onChange={e => setActivityEditFormData({...activityEditFormData, type: e.target.value})}
            >
              <option>Donation</option>
              <option>Usage</option>
              <option>Transfer</option>
            </select>
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="edit-blood-group" className="form-label text-muted fw-bold small text-uppercase mb-2">Blood Group</label>
              <select 
                id="edit-blood-group"
                className="form-select"
                value={activityEditFormData.blood_group}
                onChange={e => setActivityEditFormData({...activityEditFormData, blood_group: e.target.value})}
              >
                <option>A+</option><option>A-</option>
                <option>B+</option><option>B-</option>
                <option>O+</option><option>O-</option>
                <option>AB+</option><option>AB-</option>
              </select>
            </div>
            <div className="col-md-6">
              <label htmlFor="edit-blood-units" className="form-label text-muted fw-bold small text-uppercase mb-2">Units (Bags)</label>
              <input 
                id="edit-blood-units"
                type="number" 
                className="form-control" 
                min="1"
                value={activityEditFormData.units}
                onChange={e => setActivityEditFormData({...activityEditFormData, units: e.target.value})}
                required
              />
            </div>
          </div>
          <div className="mb-4">
            <label htmlFor="edit-blood-donor-name" className="form-label text-muted fw-bold small text-uppercase mb-2">Entity or Donor Name</label>
            <input 
              id="edit-blood-donor-name"
              type="text" 
              className="form-control" 
              value={activityEditFormData.donor_name}
              onChange={e => setActivityEditFormData({...activityEditFormData, donor_name: e.target.value})}
              required
            />
          </div>
          <div className="d-flex gap-2 mt-5">
            <button type="button" className="btn btn-glass w-100 py-2" onClick={() => setIsActivityEditModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary w-100 py-2">Save Changes</button>
          </div>
        </form>
      </Modal>

      {/* Edit Inventory Modal */}
      <Modal isOpen={isInventoryEditModalOpen} onClose={() => setIsInventoryEditModalOpen(false)} title={`Edit ${editingInventory?.type} Inventory`}>
        <form onSubmit={handleInventoryEditSubmit}>
          <div className="mb-4">
            <label htmlFor="edit-inv-units" className="form-label text-muted fw-bold small text-uppercase mb-2">Total Units Available</label>
            <input 
              id="edit-inv-units"
              type="number" 
              className="form-control" 
              value={inventoryEditFormData.units}
              onChange={e => setInventoryEditFormData({...inventoryEditFormData, units: e.target.value})}
            />
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="edit-inv-status" className="form-label text-muted fw-bold small text-uppercase mb-2">Status</label>
              <select 
                id="edit-inv-status"
                className="form-select"
                value={inventoryEditFormData.status}
                onChange={e => setInventoryEditFormData({...inventoryEditFormData, status: e.target.value})}
              >
                <option>Stable</option>
                <option>Low</option>
                <option>Critical</option>
              </select>
            </div>
            <div className="col-md-6">
              <label htmlFor="edit-inv-trend" className="form-label text-muted fw-bold small text-uppercase mb-2">Trend</label>
              <input 
                id="edit-inv-trend"
                type="text" 
                className="form-control" 
                value={inventoryEditFormData.trend}
                onChange={e => setInventoryEditFormData({...inventoryEditFormData, trend: e.target.value})}
                placeholder="e.g. +2 units"
              />
            </div>
          </div>
          <div className="d-flex gap-2 mt-5">
            <button type="button" className="btn btn-glass w-100 py-2" onClick={() => setIsInventoryEditModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary w-100 py-2">Update Inventory</button>
          </div>
        </form>
      </Modal>

      {/* Delete Confirmation */}
      <DeleteConfirmation 
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        onConfirm={handleDelete}
        itemName={deletingType === 'activity' ? `Blood ${deletingItem?.type} (${deletingItem?.group})` : `${deletingItem?.type} Inventory`}
        itemType={deletingType === 'activity' ? "Activity Record" : "Inventory Level"}
      />
    </main>
  );
};

export default BloodBank;

import React, { memo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useApp, mapPatientFromApi, createCode } from '../context/AppContext';
import { useCrud } from '../hooks/useCrud';
import { patientsApi } from '../lib/api';
import Modal from '../components/UI/Modal';
import EmptyState from '../components/UI/EmptyState';
import DeleteConfirmation from '../components/UI/DeleteConfirmation';

// Memoized individual row
const PatientRow = memo(({ patient, onEdit, onDelete }) => {
  const navigate = useNavigate();
  const { showToast } = useApp();
  return (
    <tr>
      <td className="px-4 py-4 fw-bold" style={{ fontVariantNumeric: 'tabular-nums' }}>{patient.id}</td>
      <td className="py-4">
        <div className="d-flex align-items-center">
          <div>
            <h6 className="mb-0 fw-bold">{patient.name}</h6>
            <small className="text-muted">{patient.gender}, {patient.age}y</small>
          </div>
        </div>
      </td>
      <td className="py-4">
        <span className="badge rounded-pill" style={{ background: 'var(--accents-1)', color: 'var(--geist-foreground)', border: '1px solid var(--accents-2)' }}>
          {patient.bloodGroup}
        </span>
      </td>
      <td className="py-4 text-muted small" style={{ fontVariantNumeric: 'tabular-nums' }}>{patient.lastVisit}</td>
      <td className="py-4">
        <span className={`badge rounded-pill px-3 py-1 border`} style={{ 
            background: patient.status === 'Inpatient' ? 'rgba(0, 112, 243, 0.1)' : 'rgba(16, 185, 129, 0.1)',
            color: patient.status === 'Inpatient' ? 'var(--geist-success)' : 'var(--geist-success)',
            borderColor: patient.status === 'Inpatient' ? 'rgba(0, 112, 243, 0.2)' : 'rgba(16, 185, 129, 0.2)',
            fontSize: '0.75rem'
        }}>
          <span className="pulsing-dot me-2" aria-hidden="true" style={{ width: '6px', height: '6px' }}></span>
          {patient.status}
        </span>
      </td>
      <td className="px-4 py-4 text-end">
        <button 
          className="btn btn-primary btn-sm px-3 me-2"
          onClick={() => navigate('/emr')}
        >
          EHR
        </button>
        <button 
          className="btn btn-sm btn-glass me-2"
          onClick={() => onEdit(patient)}
          title="Edit Patient"
        >
          <i className="bi bi-pencil-square"></i>
        </button>
        <button 
          className="btn btn-sm btn-glass text-danger"
          onClick={() => onDelete(patient)}
          title="Delete Patient"
        >
          <i className="bi bi-trash3"></i>
        </button>
      </td>
    </tr>
  );
});

const Patients = () => {
  const { showToast } = useApp();
  const [searchParams, setSearchParams] = useSearchParams();
  const [localSearch, setLocalSearch] = useState(searchParams.get('search') || '');
  const { 
    data: patients, 
    loading, 
    addData: addPatient, 
    updateData: updatePatient,
    removeData: deletePatient
  } = useCrud(patientsApi, mapPatientFromApi);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingPatient, setEditingPatient] = useState(null);
  const [deletingPatient, setDeletingPatient] = useState(null);

  const [formData, setFormData] = useState({
    name: '', age: '', gender: 'Male', bloodGroup: 'O+', status: 'Outpatient'
  });

  const [editFormData, setEditFormData] = useState({
    name: '', age: '', gender: 'Male', bloodGroup: 'O+', status: 'Outpatient'
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.age) {
      showToast('Please fill in all clinical identifiers.', 'warning');
      return;
    }
    try {
      const payload = {
        name: formData.name,
        age: parseInt(formData.age),
        gender: formData.gender,
        blood_group: formData.bloodGroup,
        patient_code: createCode('P'),
        status: formData.status,
        last_visit: new Date().toISOString().split('T')[0]
      };
      await addPatient(payload);
      showToast(`Patient ${formData.name} registered successfully.`);
      setIsModalOpen(false);
      setFormData({ name: '', age: '', gender: 'Male', bloodGroup: 'O+', status: 'Outpatient' });
    } catch (error) {
      showToast(error.message || 'Unable to register the patient.', 'error');
    }
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        name: editFormData.name,
        age: parseInt(editFormData.age),
        gender: editFormData.gender,
        blood_group: editFormData.bloodGroup,
        status: editFormData.status
      };
      await updatePatient(editingPatient.apiId, payload);
      showToast(`Patient profile for ${editFormData.name} updated.`);
      setIsEditModalOpen(false);
      setEditingPatient(null);
    } catch (error) {
      showToast(error.message || 'Unable to update patient profile.', 'error');
    }
  };

  const handleDelete = async () => {
    try {
      await deletePatient(deletingPatient.apiId);
      showToast(`Patient record for ${deletingPatient.name} removed from registry.`);
      setIsDeleteModalOpen(false);
      setDeletingPatient(null);
    } catch (error) {
      showToast(error.message || 'Unable to delete patient record.', 'error');
    }
  };

  const openEditModal = (p) => {
    setEditingPatient(p);
    setEditFormData({
      name: p.name,
      age: p.age,
      gender: p.gender,
      bloodGroup: p.bloodGroup,
      status: p.status
    });
    setIsEditModalOpen(true);
  };

  const filteredPatients = patients.filter(p => {
    const q = (searchParams.get('search') || '').toLowerCase();
    if (!q) return true;
    return p.name.toLowerCase().includes(q) || 
           p.id.toString().includes(q) || 
           p.bloodGroup.toLowerCase().includes(q);
  });

  return (
    <main className="patients-page p-4">
      <div className="d-flex justify-content-between align-items-center mb-5">
        <div>
          <h2 className="fw-bold mb-1">Patient Registry</h2>
          <p className="text-muted mb-0">Manage patient records and hospital admissions.</p>
        </div>
        <button 
          className="btn btn-primary px-4 py-2"
          onClick={() => setIsModalOpen(true)}
        >
          <i className="bi bi-person-plus me-2" aria-hidden="true"></i>
          Register Patient
        </button>
      </div>

      <div className="glass-card p-0 overflow-hidden border">
        <div className="p-4 border-bottom d-flex justify-content-between align-items-center bg-accents-1" style={{ background: 'var(--accents-1)' }}>
          <h6 className="fw-bold mb-0">Active Patients</h6>
          <div className="input-group w-50">
            <span className="input-group-text bg-transparent border-end-0 border-accents-2 opacity-50"><i className="bi bi-search" aria-hidden="true"></i></span>
            <input 
              type="text" 
              className="form-control border-start-0 ps-0 py-1" 
              placeholder="Filter by name, ID, or blood group…" 
              value={localSearch}
              onChange={(e) => {
                const val = e.target.value;
                setLocalSearch(val);
                setSearchParams(val ? { search: val } : {});
              }}
            />
          </div>
        </div>
        <div className="table-responsive">
          <table className="table table-hover mb-0 align-middle">
            <thead>
              <tr>
                <th className="px-4 py-3">ID</th>
                <th className="py-3">Patient Name</th>
                <th className="py-3">Blood Group</th>
                <th className="py-3">Last Visit</th>
                <th className="py-3">Status</th>
                <th className="px-4 py-3 text-end">Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan="6" className="text-center py-5"><div className="spinner-border text-primary" role="status"><span className="visually-hidden">Loading...</span></div></td></tr>
              ) : filteredPatients.length === 0 ? (
                <tr>
                  <td colSpan="6" className="p-0">
                    <EmptyState 
                      icon="bi-person-x"
                      title="No matching patients found"
                      description={`We couldn't find any outcomes matching "${searchParams.get('search') || ''}" in your registry.`}
                      actionText="Clear Search"
                      onAction={() => { setLocalSearch(''); setSearchParams({}); }}
                    />
                  </td>
                </tr>
              ) : filteredPatients.map((p) => (
                <PatientRow 
                  key={p.id} 
                  patient={p} 
                  onEdit={openEditModal}
                  onDelete={(p) => { setDeletingPatient(p); setIsDeleteModalOpen(true); }}
                />
              ))}
            </tbody>
          </table>
        </div>
        <div className="p-4 border-top d-flex justify-content-between align-items-center">
          <small className="text-muted">Showing {filteredPatients.length} active profiles</small>
          <nav aria-label="Pagination">
            <ul className="pagination pagination-sm mb-0">
              <li className="page-item disabled"><button className="page-link border">Previous</button></li>
              <li className="page-item active"><button className="page-link border">1</button></li>
              <li className="page-item"><button className="page-link border">Next</button></li>
            </ul>
          </nav>
        </div>
      </div>

      {/* Register Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title="Register New Patient"
      >
        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="patient-name" className="form-label text-muted fw-bold small text-uppercase mb-2">Full Name</label>
            <input 
              id="patient-name"
              type="text" 
              className="form-control" 
              placeholder="e.g. John Doe…" 
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
              autoComplete="name"
            />
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="patient-age" className="form-label text-muted fw-bold small text-uppercase mb-2">Age</label>
              <input 
                id="patient-age"
                type="number" 
                className="form-control" 
                placeholder="0" 
                value={formData.age}
                onChange={e => setFormData({...formData, age: e.target.value})}
              />
            </div>
            <div className="col-md-6">
              <label htmlFor="patient-gender" className="form-label text-muted fw-bold small text-uppercase mb-2">Gender</label>
              <select 
                id="patient-gender"
                className="form-select"
                value={formData.gender}
                onChange={e => setFormData({...formData, gender: e.target.value})}
              >
                <option>Male</option>
                <option>Female</option>
                <option>Other</option>
              </select>
            </div>
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="patient-blood-group" className="form-label text-muted fw-bold small text-uppercase mb-2">Blood Group</label>
              <select 
                id="patient-blood-group"
                className="form-select"
                value={formData.bloodGroup}
                onChange={e => setFormData({...formData, bloodGroup: e.target.value})}
              >
                <option>A+</option><option>A-</option>
                <option>B+</option><option>B-</option>
                <option>O+</option><option>O-</option>
                <option>AB+</option><option>AB-</option>
              </select>
            </div>
            <div className="col-md-6">
              <label htmlFor="patient-status" className="form-label text-muted fw-bold small text-uppercase mb-2">Admission Status</label>
              <select 
                id="patient-status"
                className="form-select"
                value={formData.status}
                onChange={e => setFormData({...formData, status: e.target.value})}
              >
                <option>Outpatient</option>
                <option>Inpatient</option>
                <option>Emergency</option>
              </select>
            </div>
          </div>
          <div className="d-flex gap-2 mt-5">
            <button type="button" className="btn btn-glass w-100 py-2" onClick={() => setIsModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary w-100 py-2">Register Patient</button>
          </div>
        </form>
      </Modal>

      {/* Edit Modal */}
      <Modal 
        isOpen={isEditModalOpen} 
        onClose={() => setIsEditModalOpen(false)} 
        title="Edit Patient Profile"
      >
        <form onSubmit={handleEditSubmit}>
          <div className="mb-4">
            <label htmlFor="edit-patient-name" className="form-label text-muted fw-bold small text-uppercase mb-2">Full Name</label>
            <input 
              id="edit-patient-name"
              type="text" 
              className="form-control" 
              value={editFormData.name}
              onChange={e => setEditFormData({...editFormData, name: e.target.value})}
            />
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="edit-patient-age" className="form-label text-muted fw-bold small text-uppercase mb-2">Age</label>
              <input 
                id="edit-patient-age"
                type="number" 
                className="form-control" 
                value={editFormData.age}
                onChange={e => setEditFormData({...editFormData, age: e.target.value})}
              />
            </div>
            <div className="col-md-6">
              <label htmlFor="edit-patient-gender" className="form-label text-muted fw-bold small text-uppercase mb-2">Gender</label>
              <select 
                id="edit-patient-gender"
                className="form-select"
                value={editFormData.gender}
                onChange={e => setEditFormData({...editFormData, gender: e.target.value})}
              >
                <option>Male</option>
                <option>Female</option>
                <option>Other</option>
              </select>
            </div>
          </div>
          <div className="row g-3 mb-4">
            <div className="col-md-6">
              <label htmlFor="edit-patient-blood-group" className="form-label text-muted fw-bold small text-uppercase mb-2">Blood Group</label>
              <select 
                id="edit-patient-blood-group"
                className="form-select"
                value={editFormData.bloodGroup}
                onChange={e => setEditFormData({...editFormData, bloodGroup: e.target.value})}
              >
                <option>A+</option><option>A-</option>
                <option>B+</option><option>B-</option>
                <option>O+</option><option>O-</option>
                <option>AB+</option><option>AB-</option>
              </select>
            </div>
            <div className="col-md-6">
              <label htmlFor="edit-patient-status" className="form-label text-muted fw-bold small text-uppercase mb-2">Admission Status</label>
              <select 
                id="edit-patient-status"
                className="form-select"
                value={editFormData.status}
                onChange={e => setEditFormData({...editFormData, status: e.target.value})}
              >
                <option>Outpatient</option>
                <option>Inpatient</option>
                <option>Emergency</option>
              </select>
            </div>
          </div>
          <div className="d-flex gap-2 mt-5">
            <button type="button" className="btn btn-glass w-100 py-2" onClick={() => setIsEditModalOpen(false)}>Cancel</button>
            <button type="submit" className="btn btn-primary w-100 py-2">Save Changes</button>
          </div>
        </form>
      </Modal>

      {/* Delete Modal */}
      <DeleteConfirmation 
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        onConfirm={handleDelete}
        itemName={deletingPatient?.name}
        itemType="Patient Record"
      />
    </main>
  );
};

export default Patients;
